    description: { de: "Eine der modernsten Erdölraffinerien Lateinamerikas, die eine Schlüsselrolle in der kolumbianischen Energieversorgung spielt.", hu: "Latin-Amerika egyik legmodernebb kőolajfinomítója, amely kulcsszerepet játszik a kolumbiai energiaellátásban.", ro: "Una dintre cele mai moderne rafinării de petrol din America Latină, jucând un rol cheie în aprovizionarea cu energie a Columbiei.", en: "One of the most modern oil refineries in Latin America, playing a key role in Colombia's energy supply." , es: "Una de las refinerías de petróleo más modernas de América Latina, que desempeña un papel clave en el suministro energético de Colombia.", pt: "Uma das refinarias de petróleo mais modernas da América Latina, que desempenha um papel fundamental no abastecimento energético da Colômbia.", fr: "L'une des raffineries de pétrole les plus modernes d'Amérique latine, qui joue un rôle clé dans l'approvisionnement énergétique de la Colombie."},
