      ro: ["Cea mai mare mină de cărbune la suprafață din America Latină.", "Are propria linie de cale ferată."],
      en: ["Latin America's largest open-pit coal mine.", "Has its own railway line."],
      es: ["Mayor mina de carbón a cielo abierto de América Latina.", "Cuenta con su propia línea de ferrocarril."],
      pt: ["Maior mina de carvão a céu aberto da América Latina.", "Dispõe da sua própria linha ferroviária."],
      fr: ["Plus grande mine de charbon à ciel ouvert d'Amérique latine.", "Dispose de sa propre ligne de chemin de fer."],
