      ro: ["Cea mai mare mină de cărbune în carieră din America Latină.", "Se întinde pe o suprafață totală de 69.000 de hectare.", "Dispune de o linie feroviară proprie lungă de 150 km.", "Exportă cărbunele prin portul de apă adâncă Puerto Bolívar.", "Produce anual milioane de tone de cărbune termic de calitate.", "Cel mai important angajator din departamentul La Guajira."],
      en: ["The largest open-pit coal mine in all of Latin America.", "Spans across a vast area of approximately 69,000 hectares.", "Operates its own private 150-kilometer heavy-haul railway.", "Exports coal through the dedicated deep-water Puerto Bolívar.", "Produces millions of tons of high-quality thermal coal annually.", "Acts as the primary employer in the La Guajira Department."],
      es: ["Una de las minas de carbón a cielo abierto más grandes del mundo.", "Incluye un ferrocarril privado de 150 km desde la mina hasta el mar.", "Lugar del hallazgo del fósil Titanoboa cerrejonensis.", "Produce anualmente entre 25 y 30 millones de toneladas de carbón.", "Importante motor económico y empleador en el departamento de La Guajira."],
      pt: ["Uma das maiores minas de carvão a céu aberto do mundo.", "Inclui uma ferrovia privada de 150 km da mina até ao mar.", "Local da descoberta do fóssil Titanoboa cerrejonensis.", "Produz anualmente cerca de 25-30 milhões de toneladas de carvão.", "Importante motor económico e empregador no departamento de La Guajira."],
      fr: ["L'une des plus grandes mines de charbon à ciel ouvert au monde.", "Comprend un chemin de fer privé de 150 km reliant la mine à la mer.", "Lieu de découverte du fossile Titanoboa cerrejonensis.", "Produit environ 25 à 30 millions de tonnes de charbon par an.", "Moteur économique et employeur majeur dans le département de La Guajira."],
