      es: ["La planta de ensamblaje de automóviles más productiva de Colombia.", "Ha producido más de 1,5 millones de vehículos desde su fundación en 1969.", "Principal centro de exportación de vehículos Renault hacia México, Perú y Chile.", "Galardonada en varias ocasiones por su seguridad industrial y gestión ambiental.", "Desempeñó un papel histórico en la 'motorización' de la clase media colombiana."],
      pt: ["A unidade de montagem de automóveis mais produtiva da Colômbia.", "Produziu mais de 1,5 milhões de veículos desde a sua fundação em 1969.", "Principal centro de exportação de veículos Renault para o México, Peru e Chile.", "Premiada várias vezes pela sua segurança industrial e gestão ambiental.", "Desempenhou um papel histórico na 'motorização' da classe média colombiana."],
      fr: ["Le site d'assemblage automobile le plus productif de Colombie.", "A produit plus de 1,5 million de véhicules depuis sa fondation en 1969.", "Principal carrefour d'exportation de véhicules Renault vers le Mexique, le Pérou et le Chili.", "Distinguée à plusieurs reprises pour sa sécurité industrielle et sa gestion environnementale.", "A joué un rôle historique dans la « motorisation » de la classe moyenne colombienne."],
