      ro: ["Deschiderea estimată în anul 2025", "Investiție totală de aproximativ 700 milioane USD", "Situat în Golful Urabá, lângă Turbo", "Port de mare adâncime cu un pescaj de 16,5 metri", "Cel mai apropiat port de Atlantic pentru Medellín și Bogotá", "Capacitate de peste 6,6 milioane de tone de marfă pe an"],
