      de: ["Übernahme durch Zijin Mining im Jahr 2020", "Befindet sich in der Gemeinde Buriticá, Antioquia", "Durchschnittlicher Goldgehalt von ca. 9 Gramm pro Tonne", "Jährliche Produktion von rund 250.000 Unzen Gold", "Untertagebau mit über 100 Kilometern Stollen", "Beschäftigt direkt über 3.700 Mitarbeiter"],
