      en: ["Acquired by Zijin Mining in 2020", "Located in the Buriticá municipality, Antioquia", "Average gold grade of approximately 9 grams per tonne", "Annual production of around 250,000 ounces of gold", "Underground mine with over 100 kilometers of tunnels", "Directly employs more than 3,700 people"],
      es: ["Una de las minas de oro subterráneas de mayor ley en el mundo.", "Operada por la multinacional china Zijin Mining Group.", "Primera mina de oro moderna a gran escala con permisos completos en Colombia.", "Cuenta con una planta de procesamiento de alta tecnología con capacidad de 3.000 toneladas diarias.", "Contribución importante a la formalización del sector minero en Antioquia."],
      pt: ["Uma das minas de ouro subterrâneas de mais alto teor do mundo.", "Operada pela multinacional chinesa Zijin Mining Group.", "Primeira mina de ouro moderna de grande escala com licenciamento total na Colômbia.", "Dispõe de uma unidade de processamento de alta tecnologia com capacidade de 3.000 toneladas por dia.", "Contributo importante para a formalização do setor mineiro em Antioquia."],
