      en: ["Part of Grupo Argos, founded in 1934", "Located in Yumbo, the industrial capital of Colombia", "Utilizes solar energy from the Celsia Yumbo solar farm", "Certified under ISO 14001 for environmental management", "Key supplier for the 4G highway infrastructure projects", "Implementing low-carbon cement manufacturing technologies"],
      es: ["Operada por Argos, el mayor productor de cemento en Colombia y el Caribe.", "Suministra más del 50% de la necesidad de cemento en el suroccidente de Colombia.", "Pionera en el uso de arcillas calcinadas para reducir la huella de carbono del cemento.", "Situada en el estratégico corredor industrial de Arroyohondo.", "Ganadora de múltiples premios por sus programas de responsabilidad ambiental y social."],
      pt: ["Operada pela Argos, o maior produtor de cimento da Colômbia e das Caraíbas.", "Fornece mais de 50% das necessidades de cimento no sudoeste da Colômbia.", "Pioneira na utilização de argilas calcinadas para reduzir a pegada de carbono do cimento.", "Situada no estratégico corredor industrial de Arroyohondo.", "Vencedora de múltiplos prémios pelos seus programas de responsabilidade ambiental e social."],
      fr: ["Exploitée par Argos, le plus grand producteur de ciment en Colombie et dans les Caraïbes.", "Répond à plus de 50 % des besoins en ciment du sud-ouest de la Colombie.", "Pionnière dans l'utilisation d'argiles calcinées pour réduire l'empreinte carbone du ciment.", "Située dans le corridor industriel stratégique d'Arroyohondo.", "Plusieurs fois récompensée pour ses programmes de responsabilité environnementale et sociale."],
