      pt: ["Terminal de contêineres altamente especializado no porto de Buenaventura.", "Possui guindastes Post-Panamax avançados para operações eficientes de navio para terra.", "Propriedade de um consórcio liderado pelo grupo espanhol TCB (agora parte da APM Terminals).", "Uma das instalações portuárias mais modernas e seguras da Colômbia.", "Aumentou significativamente a capacidade de movimentação de contêineres no Pacífico colombiano."],
